CREATE OR REPLACE FUNCTION public.uuid_generate_v7() RETURNS uuid AS $$
DECLARE
    ts_ms bigint;
    b bytea;
BEGIN
    -- Milliseconds since Unix epoch.
    ts_ms := floor(extract(epoch FROM clock_timestamp()) * 1000);
    -- Start with 16 random bytes.
    b := gen_random_bytes(16);

    -- Put 48-bit timestamp into the first 6 bytes (big-endian).
    b := set_byte(b, 0, ((ts_ms >> 40) & 255)::int);
    b := set_byte(b, 1, ((ts_ms >> 32) & 255)::int);
    b := set_byte(b, 2, ((ts_ms >> 24) & 255)::int);
    b := set_byte(b, 3, ((ts_ms >> 16) & 255)::int);
    b := set_byte(b, 4, ((ts_ms >> 8) & 255)::int);
    b := set_byte(b, 5, (ts_ms & 255)::int);

    -- Set version (7) in high nibble of byte 6.
    b := set_byte(b, 6, ((get_byte(b, 6) & 15) | 112)::int);
    -- Set variant to RFC 4122 (10xx) in byte 8.
    b := set_byte(b, 8, ((get_byte(b, 8) & 63) | 128)::int);

    RETURN encode(b, 'hex')::uuid;
END;
$$ LANGUAGE plpgsql;
